INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 1, 'English', 'Which constitutional principle requires government authority to remain answerable to the people?', '["Public accountability","Private ownership of agencies","Hereditary succession","Military supremacy"]'::jsonb, 0, 'Public accountability makes officials answerable for the exercise of public power Therefore, the correct option is "Public accountability." The other choices fail because the other choices replace democratic accountability with private, hereditary, or military control.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which constitutional principle requires government authority to remain answerable to the people?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 1, 'English', 'A law must respect the separation of powers. Which branch primarily makes statutes?', '["The legislative branch","The executive branch","The judicial branch","Local school boards"]'::jsonb, 0, 'Congress, the legislative branch, exercises legislative power under Article VI Therefore, the correct option is "The legislative branch." The other choices fail because the executive and judicial branches implement or interpret law, while school boards are not a national branch.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('A law must respect the separation of powers. Which branch primarily makes statutes?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 1, 'English', 'Which institution tries impeachment cases under the 1987 Constitution?', '["The Senate","The House of Representatives","The Commission on Audit","The Supreme Court as a trial jury"]'::jsonb, 0, 'The Senate has the sole power to try and decide impeachment cases after the House initiates them Therefore, the correct option is "The Senate." The other choices fail because the House initiates, while COA and the Supreme Court do not act as the impeachment trial body.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which institution tries impeachment cases under the 1987 Constitution?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 1, 'English', 'The President is the commander-in-chief of which constitutional institution?', '["The armed forces of the Philippines","All private corporations","Every foreign military","The independent constitutional commissions"]'::jsonb, 0, 'Article VII makes the President commander-in-chief of the armed forces Therefore, the correct option is "The armed forces of the Philippines." The other choices fail because the other choices are outside that constitutional command relationship.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('The President is the commander-in-chief of which constitutional institution?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 1, 'English', 'Which right is most directly involved when government prevents a peaceful newspaper from criticizing a policy?', '["Freedom of the press","Right to travel only","Right against double jeopardy","Right to form a family"]'::jsonb, 0, 'Freedom of the press protects publication and criticism subject to lawful limits Therefore, the correct option is "Freedom of the press." The other choices fail because the other rights do not directly concern publication of criticism.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which right is most directly involved when government prevents a peaceful newspaper from criticizing a policy?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 1, 'English', 'A search of a home generally requires a judicial warrant based on probable cause. This rule protects the:', '["Right against unreasonable searches and seizures","Right to information on public matters","Right to suffrage","Right to just compensation"]'::jsonb, 0, 'The Bill of Rights protects persons and homes from unreasonable searches and seizures Therefore, the correct option is "Right against unreasonable searches and seizures." The other choices fail because the alternatives concern information, voting, or property compensation rather than search procedure.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('A search of a home generally requires a judicial warrant based on probable cause. This rule protects the:')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 1, 'English', 'Which body audits government funds and property?', '["Commission on Audit","Commission on Elections","Civil Service Commission","Department of Trade and Industry"]'::jsonb, 0, 'The Constitution assigns government auditing to the Commission on Audit Therefore, the correct option is "Commission on Audit." The other choices fail because the other bodies have election, civil-service, or trade functions.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which body audits government funds and property?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 1, 'English', 'What is the constitutional term for citizenship acquired from birth without needing an act to acquire or perfect it?', '["Natural-born citizenship","Temporary residency","Naturalized status only","Tourist status"]'::jsonb, 0, 'Natural-born citizens are citizens from birth without needing an act to acquire or perfect citizenship Therefore, the correct option is "Natural-born citizenship." The other choices fail because residency, naturalization, and tourism describe different legal statuses.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('What is the constitutional term for citizenship acquired from birth without needing an act to acquire or perfect it?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 1, 'English', 'Which constitutional commission administers the civil service?', '["Civil Service Commission","Commission on Audit","Commission on Elections","Commission on Human Rights"]'::jsonb, 0, 'The Civil Service Commission administers the government personnel system Therefore, the correct option is "Civil Service Commission." The other choices fail because COA audits, COMELEC administers elections, and CHR investigates human-rights concerns.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which constitutional commission administers the civil service?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 1, 'English', 'The constitutional guarantee that no person may be deprived of life, liberty, or property without due process is a protection against:', '["Arbitrary government action","All private disagreements","Every tax obligation","Routine filing errors"]'::jsonb, 0, 'Due process requires fair legal procedures and a lawful basis before deprivation Therefore, the correct option is "Arbitrary government action." The other choices fail because the alternatives are not the constitutional mischief targeted by due process.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('The constitutional guarantee that no person may be deprived of life, liberty, or property without due process is a protection against:')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 1, 'English', 'Which statement best describes the constitutional role of the judiciary?', '["It settles actual controversies involving enforceable rights","It writes the annual national budget alone","It appoints every local official","It conducts all elections"]'::jsonb, 0, 'The judiciary resolves actual controversies and may review grave abuse or constitutional conflicts Therefore, the correct option is "It settles actual controversies involving enforceable rights." The other choices fail because budgeting, local appointments, and election administration belong primarily to other institutions.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which statement best describes the constitutional role of the judiciary?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 1, 'English', 'Under the Constitution, the privilege of the writ of habeas corpus relates most closely to:', '["Protection against unlawful detention","Ownership of a registered vehicle","Approval of a business name","Assessment of real property tax"]'::jsonb, 0, 'Habeas corpus tests unlawful restraint of personal liberty Therefore, the correct option is "Protection against unlawful detention." The other choices fail because the alternatives concern property, business registration, or taxation.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Under the Constitution, the privilege of the writ of habeas corpus relates most closely to:')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 1, 'English', 'Which statement reflects the constitutional policy on civilian authority?', '["Civilian authority is supreme over the military","Military officers may replace elected institutions whenever they wish","Courts are subordinate to private groups","Local officials command the national armed forces"]'::jsonb, 0, 'The Constitution places civilian authority above the military in a democratic republic Therefore, the correct option is "Civilian authority is supreme over the military." The other choices fail because the other choices reverse or invent the constitutional chain of authority.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which statement reflects the constitutional policy on civilian authority?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 1, 'English', 'A valid classification for equal-protection purposes should be related to the law purpose and apply to:', '["All members of the same class","Only the official who drafted it","Foreign visitors only","One named person only"]'::jsonb, 0, 'Equal protection requires a reasonable classification that applies alike to all in the same class Therefore, the correct option is "All members of the same class." The other choices fail because the other choices are arbitrary limits and do not describe equal treatment.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('A valid classification for equal-protection purposes should be related to the law purpose and apply to:')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 1, 'English', 'Which governmental power is exercised when the state takes private property for public use with payment?', '["Eminent domain","Police patrol only","Judicial notice","Legislative privilege"]'::jsonb, 0, 'Eminent domain is the taking of private property for public use with just compensation Therefore, the correct option is "Eminent domain." The other choices fail because the alternatives do not describe a compensated public-use taking.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which governmental power is exercised when the state takes private property for public use with payment?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 1, 'English', 'A bill becomes a law over the President''s veto when:', '["Two-thirds of all the members of each House vote to pass it again","A single senator announces approval","A local mayor signs it","The Supreme Court writes a replacement bill"]'::jsonb, 0, 'The Constitution permits Congress to override a veto by a two-thirds vote of all members of each House Therefore, the correct option is "Two-thirds of all the members of each House vote to pass it again." The other choices fail because the other actions do not satisfy the constitutional override requirement.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('A bill becomes a law over the President''s veto when:')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 1, 'English', 'Which is a constitutional qualification for a Philippine senator?', '["At least 35 years old on election day","At least 18 years old on election day","A licensed lawyer in every case","A former governor in every case"]'::jsonb, 0, 'The Constitution requires a senator to be at least 35 years old on election day Therefore, the correct option is "At least 35 years old on election day." The other choices fail because the other choices are not universal constitutional qualifications.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which is a constitutional qualification for a Philippine senator?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 1, 'English', 'Which right allows qualified citizens to participate directly in choosing public officials?', '["Suffrage","Habeas data","Freedom from impairment of contracts","Right to bail only"]'::jsonb, 0, 'Suffrage is the constitutional right to vote subject to legal qualifications Therefore, the correct option is "Suffrage." The other choices fail because the alternatives concern information, contracts, or criminal procedure.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which right allows qualified citizens to participate directly in choosing public officials?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 1, 'English', 'The constitutional ban on ex post facto laws means government may not:', '["Punish an act that was not criminal when done","Collect a lawful tax","Require a public permit","Publish a statute"]'::jsonb, 0, 'An ex post facto law retroactively makes conduct criminal or increases its punishment Therefore, the correct option is "Punish an act that was not criminal when done." The other choices fail because the other choices are not retroactive criminal punishment.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('The constitutional ban on ex post facto laws means government may not:')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 1, 'English', 'Which constitutional office is designed to investigate and prosecute illegal acts of public officials?', '["The Office of the Ombudsman","The Philippine Sports Commission","The National Library","The Weather Bureau"]'::jsonb, 0, 'The Ombudsman investigates and prosecutes alleged illegal acts or omissions of public officials as provided by law Therefore, the correct option is "The Office of the Ombudsman." The other choices fail because the other offices do not have that constitutional accountability function.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which constitutional office is designed to investigate and prosecute illegal acts of public officials?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 1, 'English', 'Local autonomy means local government units may:', '["Manage local affairs within the Constitution and national law","Ignore every national statute","Declare war independently","Print national currency"]'::jsonb, 0, 'Local autonomy allows self-government within constitutional and statutory limits Therefore, the correct option is "Manage local affairs within the Constitution and national law." The other choices fail because the alternatives claim powers reserved to the national government or prohibited by law.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Local autonomy means local government units may:')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 1, 'English', 'Which constitutional commission conducts elections and enforces election laws?', '["Commission on Elections","Commission on Audit","Civil Service Commission","Department of Finance"]'::jsonb, 0, 'COMELEC administers and enforces election laws Therefore, the correct option is "Commission on Elections." The other choices fail because the other bodies audit, manage civil service, or handle fiscal administration.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which constitutional commission conducts elections and enforces election laws?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 1, 'English', 'The constitutional right to information generally concerns:', '["Matters of public concern subject to lawful limitations","Private passwords of every citizen","All confidential medical records","Every sealed court exhibit without exception"]'::jsonb, 0, 'The right to information covers matters of public concern subject to constitutional and statutory limits Therefore, the correct option is "Matters of public concern subject to lawful limitations." The other choices fail because the other choices ignore privacy, privilege, or other lawful restrictions.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('The constitutional right to information generally concerns:')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 1, 'English', 'Which statement about a person accused of a crime is constitutionally sound?', '["The accused is presumed innocent until the contrary is proved","The accused must prove innocence before trial","A rumor is conclusive proof","A confession is required in every case"]'::jsonb, 0, 'Presumption of innocence places the burden of proof on the prosecution Therefore, the correct option is "The accused is presumed innocent until the contrary is proved." The other choices fail because the other choices reverse the burden or treat unreliable material as conclusive.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which statement about a person accused of a crime is constitutionally sound?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 1, 'English', 'A constitutional limitation on public funds is that money may be paid out only:', '["Pursuant to an appropriation made by law","When a private donor requests it","Whenever an employee asks orally","Without any accounting record"]'::jsonb, 0, 'Public funds require legal appropriation and proper public accountability Therefore, the correct option is "Pursuant to an appropriation made by law." The other choices fail because the other choices bypass the legal and accounting safeguards.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('A constitutional limitation on public funds is that money may be paid out only:')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 2, 'English', 'Under RA 6713, which interest must public officials place above personal interest?', '["Public interest","A supplier''s interest","A relative''s business interest","A personal investment target"]'::jsonb, 0, 'Section 4 requires public interest to be upheld over personal interest Therefore, the correct option is "Public interest." The other choices fail because the other choices are private interests that the norm is meant to subordinate.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Under RA 6713, which interest must public officials place above personal interest?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 2, 'English', 'A public employee receives a valuable gift from a bidder whose transaction the employee handles. The safer statutory conclusion is that the gift is:', '["A prohibited gift connected with official duties","Automatically harmless because it is wrapped","Required by professionalism","A personal salary increase"]'::jsonb, 0, 'Section 7 prohibits soliciting or accepting gifts connected with official duties or regulated transactions Therefore, the correct option is "A prohibited gift connected with official duties." The other choices fail because packaging, professionalism, and salary labels do not remove the conflict.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('A public employee receives a valuable gift from a bidder whose transaction the employee handles. The safer statutory conclusion is that the gift is:')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 2, 'English', 'RA 6713 generally requires a public official to respond to a public letter within:', '["Fifteen working days","One calendar hour","One decade","Only after an election"]'::jsonb, 0, 'Section 5 calls for a response within fifteen working days and states the action taken Therefore, the correct option is "Fifteen working days." The other choices fail because the other time periods do not match the statutory duty.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('RA 6713 generally requires a public official to respond to a public letter within:')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 2, 'English', 'The annual deadline stated in RA 6713 for filing the SALN is:', '["On or before April 30","December 31 only","The employee''s birthday","Whenever an audit begins"]'::jsonb, 0, 'Section 8 states that the annual SALN is filed on or before April 30 Therefore, the correct option is "On or before April 30." The other choices fail because the other dates are not the statutory annual deadline.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('The annual deadline stated in RA 6713 for filing the SALN is:')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 2, 'English', 'A SALN is generally filed after assumption of office within:', '["Thirty days","Three years","One working hour","Only after promotion"]'::jsonb, 0, 'Section 8 requires filing within thirty days after assumption of office Therefore, the correct option is "Thirty days." The other choices fail because the other choices do not state the statutory period.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('A SALN is generally filed after assumption of office within:')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 2, 'English', 'When a public officer separates from service, the SALN is generally due within:', '["Thirty days after separation","Ten years after separation","Only if asked by a neighbor","Before the officer''s first appointment"]'::jsonb, 0, 'Section 8 requires a filing within thirty days after separation from service Therefore, the correct option is "Thirty days after separation." The other choices fail because the alternatives use an incorrect trigger or no legal duty.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('When a public officer separates from service, the SALN is generally due within:')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 2, 'English', 'Political neutrality under RA 6713 means a public employee should:', '["Serve people without unfair discrimination based on party affiliation","Refuse service to political opponents","Campaign during every transaction","Serve only campaign donors"]'::jsonb, 0, 'Political neutrality requires service without unfair discrimination based on party affiliation or preference Therefore, the correct option is "Serve people without unfair discrimination based on party affiliation." The other choices fail because the other choices are partisan discrimination.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Political neutrality under RA 6713 means a public employee should:')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 2, 'English', 'The norm of simple living asks officials and their families to:', '["Lead modest lives appropriate to position and income","Display wealth to prove competence","Hide every lawful asset","Reject all lawful compensation"]'::jsonb, 0, 'Simple living means modest conduct appropriate to position and lawful income Therefore, the correct option is "Lead modest lives appropriate to position and income." The other choices fail because the alternatives promote extravagance, concealment, or an unrelated refusal of compensation.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('The norm of simple living asks officials and their families to:')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 2, 'English', 'Which act best illustrates professionalism under RA 6713?', '["Discharging duties with excellence, skill, and dedication","Selling preferential access to a file","Delaying every request without reason","Using public equipment for private profit"]'::jsonb, 0, 'Professionalism calls for excellence, intelligence, skill, devotion, and dedication to duty Therefore, the correct option is "Discharging duties with excellence, skill, and dedication." The other choices fail because the other choices are patronage, neglect, or misuse.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which act best illustrates professionalism under RA 6713?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 2, 'English', 'A conflict of interest exists when an official''s private business interest may be:', '["Opposed to or affected by faithful performance of official duty","Completely unrelated to any official action","A hobby with no financial connection","A public holiday"]'::jsonb, 0, 'RA 6713 defines conflict of interest around a private interest opposed to or affected by official duty Therefore, the correct option is "Opposed to or affected by faithful performance of official duty." The other choices fail because the other choices do not create the required official-private connection.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('A conflict of interest exists when an official''s private business interest may be:')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 2, 'English', 'Divestment under RA 6713 means:', '["Voluntarily and completely disposing of a conflicting interest","Moving an asset to another desk","Listing an asset without changing ownership","Borrowing a colleague''s ID"]'::jsonb, 0, 'Divestment transfers title or disposes of the conflicting interest so the official no longer holds it Therefore, the correct option is "Voluntarily and completely disposing of a conflicting interest." The other choices fail because the alternatives do not remove ownership or control.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Divestment under RA 6713 means:')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 2, 'English', 'A public employee using confidential procurement data to help a friend violates the rule against:', '["Disclosure or misuse of confidential information","Simple living only","Annual leave scheduling","Public speaking"]'::jsonb, 0, 'Section 7 bars using or divulging confidential information to advance private interests or prejudice public interest Therefore, the correct option is "Disclosure or misuse of confidential information." The other choices fail because the other choices do not describe misuse of nonpublic official information.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('A public employee using confidential procurement data to help a friend violates the rule against:')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 2, 'English', 'Which duty supports openness in government service?', '["Making public documents accessible during reasonable working hours","Destroying all records immediately","Giving documents only to relatives","Refusing to explain procedures"]'::jsonb, 0, 'RA 6713 directs offices to make public documents accessible and information understandable Therefore, the correct option is "Making public documents accessible during reasonable working hours." The other choices fail because the other choices defeat transparency and public access.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which duty supports openness in government service?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 2, 'English', 'For official papers, RA 6713 says they should contain, as far as practicable, no more than:', '["Three signatories","Thirty signatories","One hundred signatories","No identifying signatory"]'::jsonb, 0, 'Section 5 limits official papers to not more than three signatories when practicable Therefore, the correct option is "Three signatories." The other choices fail because the other choices ignore the anti-red-tape requirement.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('For official papers, RA 6713 says they should contain, as far as practicable, no more than:')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 2, 'English', 'Which agency has primary responsibility for administration and enforcement of RA 6713?', '["Civil Service Commission","Department of Tourism","National Archives alone","A private contractor"]'::jsonb, 0, 'Section 12 assigns primary administration and enforcement to the Civil Service Commission Therefore, the correct option is "Civil Service Commission." The other choices fail because the other choices are not the agency named by the statute.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which agency has primary responsibility for administration and enforcement of RA 6713?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 2, 'English', 'A public officer recommending a person to a private enterprise with a regular pending transaction with the officer''s office is:', '["A prohibited outside-employment-related act","Always required by courtesy","A SALN filing date","A constitutional amendment"]'::jsonb, 0, 'Section 7 prohibits that recommendation during incumbency Therefore, the correct option is "A prohibited outside-employment-related act." The other choices fail because the other choices misclassify the conduct and do not address the conflict.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('A public officer recommending a person to a private enterprise with a regular pending transaction with the officer''s office is:')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 2, 'English', 'Which statement about public service and relatives is consistent with RA 6713?', '["Officials must avoid undue favors to relatives because of office","Officials must award every contract to relatives","Relatives are exempt from all ethical rules","Family preference is always public interest"]'::jsonb, 0, 'The norm of justness and sincerity bars undue favors to relatives on account of office, subject to the statutory qualification Therefore, the correct option is "Officials must avoid undue favors to relatives because of office." The other choices fail because the other choices turn public power into automatic family patronage.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which statement about public service and relatives is consistent with RA 6713?')));
