INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 7, 'English', 'Which sentence contains an error in subject-verb agreement?', '["The list of names is on the desk.","The reports from each unit are ready.","The set of keys were returned.","The clerks review the forms."]'::jsonb, 2, 'The subject set is singular, so the verb should be was, not were Therefore, the correct option is "The set of keys were returned.." The other choices fail because the other sentences correctly match their verbs to their subjects.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which sentence contains an error in subject-verb agreement?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 7, 'English', 'Which sentence contains an incorrect pronoun case?', '["The supervisor spoke with Ana and me.","He and I prepared the index.","Between you and I, the file is incomplete.","They submitted their reports."]'::jsonb, 2, 'The preposition between requires the object pronoun me, so the phrase should be between you and me Therefore, the correct option is "Between you and I, the file is incomplete.." The other choices fail because the other sentences use pronouns in appropriate cases.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which sentence contains an incorrect pronoun case?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 7, 'English', 'Which sentence contains a dangling modifier?', '["After reading the memo, Carlo filed it.","While waiting for the bus, the clerk reviewed notes.","After the audit ended, the team issued a summary.","Walking through the hallway, the lights were unusually bright."]'::jsonb, 3, 'Walking describes a person, but the sentence makes the lights appear to be walking Therefore, the correct option is "Walking through the hallway, the lights were unusually bright.." The other choices fail because the other sentences attach their introductory phrases to sensible actors.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which sentence contains a dangling modifier?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 7, 'English', 'Which sentence uses a comma incorrectly?', '["The office opened at eight, and visitors entered.","After lunch, the team resumed work.","The clerk who arrived early, organized the files.","The report was concise, clear, and complete."]'::jsonb, 2, 'A restrictive who-clause should not be separated from its subject by that comma Therefore, the correct option is "The clerk who arrived early, organized the files.." The other choices fail because the other sentences use commas for independent clauses, introductory phrases, or a series.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which sentence uses a comma incorrectly?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 7, 'English', 'Which sentence has an error in verb tense consistency?', '["The analyst reviewed the figures and corrected the table.","The clerk checks the form and records the date.","The team inspected the room and files a report yesterday.","The officer will call and will confirm the schedule."]'::jsonb, 2, 'The past-time marker yesterday requires filed, not present-tense files Therefore, the correct option is "The team inspected the room and files a report yesterday.." The other choices fail because the other sentences keep their verbs in compatible time frames.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which sentence has an error in verb tense consistency?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 7, 'English', 'Which sentence uses an ambiguous pronoun?', '["When Mara called Liza, she was already outside.","Mara called Liza after lunch.","Liza signed the attendance sheet.","The supervisor called the office."]'::jsonb, 0, 'She could refer to either Mara or Liza, so the pronoun lacks a clear antecedent Therefore, the correct option is "When Mara called Liza, she was already outside.." The other choices fail because the other choices name their subjects clearly.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which sentence uses an ambiguous pronoun?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 8, 'English', 'Which option is a complex sentence?', '["The clerk sorted the folders.","The clerk sorted the folders, and the aide labeled them.","Although the queue was long, the clerk remained patient.","Sort the folders now."]'::jsonb, 2, 'Although introduces a dependent clause joined to an independent clause Therefore, the correct option is "Although the queue was long, the clerk remained patient.." The other choices fail because the other choices are simple, compound, or imperative rather than complex.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which option is a complex sentence?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 8, 'English', 'Which option is a compound sentence?', '["The report is complete.","Because the report is complete.","The report is complete, and the supervisor signed it.","Complete report."]'::jsonb, 2, 'The sentence joins two independent clauses with and Therefore, the correct option is "The report is complete, and the supervisor signed it.." The other choices fail because the other choices contain one clause or a fragment.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which option is a compound sentence?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 8, 'English', 'Which sentence has correct parallel structure?', '["The job requires filing, checking, and answering calls.","The job requires filing, checking, and to answer calls.","The job requires file, checking, and calls.","The job requires to file, checking, and answering."]'::jsonb, 0, 'The three gerunds filing, checking, and answering have the same grammatical form Therefore, the correct option is "The job requires filing, checking, and answering calls.." The other choices fail because the other choices mix gerunds, infinitives, nouns, and verbs.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which sentence has correct parallel structure?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 8, 'English', 'Which revision removes the run-on sentence from ''The form was incomplete the clerk returned it''?', '["The form was incomplete, so the clerk returned it.","The form was incomplete the clerk returned it.","The form was incomplete, the clerk returned it.","The form incomplete returned clerk it."]'::jsonb, 0, 'A comma and coordinating conjunction correctly join the two independent clauses Therefore, the correct option is "The form was incomplete, so the clerk returned it.." The other choices fail because the other choices retain a run-on, create a comma splice, or omit sentence structure.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which revision removes the run-on sentence from ''The form was incomplete the clerk returned it''?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 8, 'English', 'Which option is a sentence fragment?', '["The office closes at five.","When the office closes at five.","The office closed at five, and the guard left.","Close the office at five."]'::jsonb, 1, 'When introduces a dependent clause that lacks an independent clause Therefore, the correct option is "When the office closes at five.." The other choices fail because the other choices are complete statements or an imperative.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which option is a sentence fragment?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 9, 'English', 'Which sentence is the best topic sentence for a paragraph about faster permit processing?', '["Clear checklists can reduce avoidable permit delays.","The building has three windows.","Yesterday was humid.","Some forms are blue."]'::jsonb, 0, 'The first sentence states the paragraph''s controlling idea about reducing delays Therefore, the correct option is "Clear checklists can reduce avoidable permit delays.." The other choices fail because the other choices are narrow details or unrelated facts.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which sentence is the best topic sentence for a paragraph about faster permit processing?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 9, 'English', 'Which order best organizes instructions for submitting a form?', '["Complete the fields, attach proof, review the entries, then submit.","Submit first, then decide which form is needed.","Archive the form before writing on it.","Choose a filing shelf before reading the instructions."]'::jsonb, 0, 'A process is clearest when actions follow the actual submission sequence Therefore, the correct option is "Complete the fields, attach proof, review the entries, then submit.." The other choices fail because the other choices reverse or omit essential steps.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which order best organizes instructions for submitting a form?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 9, 'English', 'A paragraph has one sentence about parking and four about document security. To improve unity, the writer should:', '["Remove or relocate the unrelated parking sentence","Add three more parking sentences","Delete the document-security details","Change every verb to past tense"]'::jsonb, 0, 'Unity requires every sentence to support the paragraph''s controlling idea Therefore, the correct option is "Remove or relocate the unrelated parking sentence." The other choices fail because the other choices increase distraction or alter grammar without fixing relevance.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('A paragraph has one sentence about parking and four about document security. To improve unity, the writer should:')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 9, 'English', 'Which transition best signals a contrast?', '["However","Similarly","Therefore","For example"]'::jsonb, 0, 'However introduces a contrast between ideas Therefore, the correct option is "However." The other choices fail because the other choices signal similarity, result, or illustration.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which transition best signals a contrast?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 9, 'English', 'Which transition best signals a result?', '["Therefore","Meanwhile","For instance","Likewise"]'::jsonb, 0, 'Therefore introduces a conclusion or result Therefore, the correct option is "Therefore." The other choices fail because the other choices signal time, example, or similarity.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which transition best signals a result?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 10, 'English', 'A notice says, ''Visitors who submit complete forms before noon receive same-day screening.'' Who qualifies?', '["A visitor with a complete form submitted at 11:30 a.m.","A visitor with an incomplete form at 10:00 a.m.","A visitor with a complete form submitted at 1:00 p.m.","A person who never submits a form"]'::jsonb, 0, 'The stated conditions are completeness and submission before noon Therefore, the correct option is "A visitor with a complete form submitted at 11:30 a.m.." The other choices fail because the other choices miss completeness, miss the deadline, or omit submission.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('A notice says, ''Visitors who submit complete forms before noon receive same-day screening.'' Who qualifies?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 10, 'English', 'A report says errors fell after peer review, but it does not compare other offices. The safest inference is:', '["Peer review may have contributed to the decline","Peer review alone caused every improvement","Errors will never return","Other offices cannot use peer review"]'::jsonb, 0, 'The before-and-after association supports a cautious possibility, not proof of sole causation Therefore, the correct option is "Peer review may have contributed to the decline." The other choices fail because the other choices claim certainty not established by the report.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('A report says errors fell after peer review, but it does not compare other offices. The safest inference is:')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 10, 'English', 'A paragraph states that online forms reduce encoding time but require reliable internet. Its balanced conclusion is:', '["Online forms offer efficiency but depend on connectivity","Online forms have no possible benefit","Internet access is irrelevant","Paper forms are always illegal"]'::jsonb, 0, 'The conclusion preserves both the benefit and the stated limitation Therefore, the correct option is "Online forms offer efficiency but depend on connectivity." The other choices fail because the other choices ignore or reverse a material part of the passage.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('A paragraph states that online forms reduce encoding time but require reliable internet. Its balanced conclusion is:')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 10, 'English', 'If a memo says the pilot served 30 of 40 applicants, what fraction were served?', '["Three-fourths","One-fourth","Two-fifths","Four-thirds"]'::jsonb, 0, 'Thirty divided by forty simplifies to three-fourths Therefore, the correct option is "Three-fourths." The other choices fail because the other fractions do not equal the stated served-to-total ratio.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('If a memo says the pilot served 30 of 40 applicants, what fraction were served?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 10, 'English', 'A policy says records are retained for five years unless a litigation hold applies. What is the exception?', '["A litigation hold","A quiet office","A new printer","A staff meeting"]'::jsonb, 0, 'The phrase unless identifies the litigation hold as the exception Therefore, the correct option is "A litigation hold." The other choices fail because the other choices are not listed as exceptions in the policy.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('A policy says records are retained for five years unless a litigation hold applies. What is the exception?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 6, 'Filipino', 'Piliin ang wastong gamit: ''_____ dumating ang pinuno, sinimulan ang pulong.''', '["Nang","Ng","Nang sa","Kung"]'::jsonb, 0, 'Ginagamit ang nang bilang pangatnig na nag-uugnay sa kilos at oras Therefore, the correct option is "Nang." The other choices fail because ang ng ay pananda ng pagmamay-ari o layon, at hindi angkop ang iba sa pangungusap.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Piliin ang wastong gamit: ''_____ dumating ang pinuno, sinimulan ang pulong.''')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 6, 'English', 'Alin ang wastong pangungusap?', '["Mabilis na tumakbo ang bata.","Mabilis nang tumakbo ang bata na.","Mabilis ng tumakbo ang bata.","Mabilis na ang tumakbo bata."]'::jsonb, 0, 'Wasto ang ayos na pang-abay na sinusundan ng na at pandiwa Therefore, the correct option is "Mabilis na tumakbo ang bata.." The other choices fail because ang ibang pagpipilian ay may maling gamit ng pang-angkop o maling ayos.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Alin ang wastong pangungusap?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 6, 'English', 'Piliin ang wastong salita: ''Mabuting _____ ang panukala bago ito pagtibayin.''', '["subukin","subukan","sinubok","pagsubok"]'::jsonb, 1, 'Ang subukan ay nangangahulugang tangkaing gawin o siyasatin ang isang bagay Therefore, the correct option is "subukan." The other choices fail because ang subukin ay karaniwang may ibang gamit, habang ang dalawang anyo ay hindi angkop sa puwang.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Piliin ang wastong salita: ''Mabuting _____ ang panukala bago ito pagtibayin.''')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 7, 'English', 'Alin ang wastong baybay?', '["pinagkakakitaan","pinagkakakitaan","pinagkakitaan","pinagkakitaan"]'::jsonb, 0, 'Ang wastong anyo ng salita ay pinagkakakitaan Therefore, the correct option is "pinagkakakitaan." The other choices fail because ang ibang pagpipilian ay kaparehong anyo lamang sa payak na anyo at hindi dapat gamitin bilang distractor.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Alin ang wastong baybay?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 7, 'English', 'Alin ang wastong gamit ng ''rin'' at ''din''?', '["Mabuti rin ang mungkahi niya.","Mabuti din ang mungkahi niya kapag patinig ang hulihan.","Mabuti rin ang mungkahi niya ay.","Mabuti din rin ang mungkahi niya."]'::jsonb, 0, 'Karaniwang ginagamit ang rin kapag patinig ang huling tunog ng naunang salita, gaya ng mabuti Therefore, the correct option is "Mabuti rin ang mungkahi niya.." The other choices fail because ang ibang pangungusap ay may maling tuntunin o dobleng pang-abay.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Alin ang wastong gamit ng ''rin'' at ''din''?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 8, 'English', 'Alin ang nasa karaniwang ayos?', '["Nagsumite ng ulat ang kawani.","Ng ulat nagsumite ang kawani.","Ang kawani ng ulat nagsumite.","Nagsumite ang ulat ng kawani."]'::jsonb, 0, 'Sa karaniwang ayos, nauuna ang panaguri at sumusunod ang simuno Therefore, the correct option is "Nagsumite ng ulat ang kawani.." The other choices fail because ang ibang ayos ay baligtad, malabo, o nagbabago ng kahulugan.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Alin ang nasa karaniwang ayos?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 8, 'English', 'Alin ang pangungusap na nasa di-karaniwang ayos?', '["Ang kawani ay nagsumite ng ulat.","Nagsumite ng ulat ang kawani.","Nagsumite ang kawani ng ulat.","Ulat ang nagsumite ng kawani."]'::jsonb, 0, 'Sa di-karaniwang ayos, nauuna ang simuno at karaniwang ginagamit ang ay Therefore, the correct option is "Ang kawani ay nagsumite ng ulat.." The other choices fail because ang ibang pagpipilian ay karaniwang ayos o mali ang ugnayan ng mga salita.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Alin ang pangungusap na nasa di-karaniwang ayos?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 10, 'English', 'Basahin: ''Maagang nagbukas ang tanggapan upang mapaglingkuran ang mga aplikante.'' Ano ang dahilan ng maagang pagbubukas?', '["Mapaglingkuran ang mga aplikante","Magsara nang mas maaga","Magdaos ng paligsahan","Magpalit ng gusali"]'::jsonb, 0, 'Ang pariralang upang mapaglingkuran ang mga aplikante ay nagsasaad ng layunin Therefore, the correct option is "Mapaglingkuran ang mga aplikante." The other choices fail because ang ibang sagot ay hindi binanggit o salungat sa pangungusap.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Basahin: ''Maagang nagbukas ang tanggapan upang mapaglingkuran ang mga aplikante.'' Ano ang dahilan ng maagang pagbubukas?')));
