INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 12, 'English', 'If ▲ means plus and ■ means minus, what is 9 ▲ 4 ■ 3?', '["10","12","16","6"]'::jsonb, 0, 'Replace the symbols and compute 9 plus 4 minus 3, which equals 10 Therefore, the correct option is "10." The other choices fail because the other choices misread one symbol or perform the arithmetic incorrectly.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('If ▲ means plus and ■ means minus, what is 9 ▲ 4 ■ 3?')));
