INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 12, 'English', 'A sequence follows add 3, then add 5, then add 7, repeating. What comes after 10, 13, 18, 25?', '["28","30","32","34"]'::jsonb, 0, 'The next increment is 3, so 25 plus 3 equals 28 Therefore, the correct option is "28." The other choices fail because the other choices use a different increment or skip the repeating pattern.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('A sequence follows add 3, then add 5, then add 7, repeating. What comes after 10, 13, 18, 25?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 12, 'English', 'If all R are S and no S are T, which must be true?', '["No R are T","All T are R","Some R are T","All S are R"]'::jsonb, 0, 'R is contained in S, and S excludes T, so R also excludes T Therefore, the correct option is "No R are T." The other choices fail because the other choices reverse or overstate the given relationships.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('If all R are S and no S are T, which must be true?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 12, 'English', 'Four symbols rotate one place left: A, B, C, D becomes B, C, D, A. What is the next rotation?', '["C, D, A, B","D, A, B, C","A, C, B, D","B, A, D, C"]'::jsonb, 0, 'Rotating the current sequence left again moves B to the end after C and D, giving C, D, A, B Therefore, the correct option is "C, D, A, B." The other choices fail because the other sequences rotate in another direction or change the order.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Four symbols rotate one place left: A, B, C, D becomes B, C, D, A. What is the next rotation?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 13, 'English', 'Claim: ''Install a queue display because visitors cannot tell when they will be called.'' The needed assumption is:', '["A display can give visitors useful queue information","Visitors never wait","The office will abolish service numbers","The display must be outdoors"]'::jsonb, 0, 'The recommendation depends on a display being capable of informing waiting visitors Therefore, the correct option is "A display can give visitors useful queue information." The other choices fail because the other choices are unnecessary or contradict the proposed solution.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Claim: ''Install a queue display because visitors cannot tell when they will be called.'' The needed assumption is:')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 13, 'English', 'All verified forms carry a validation stamp. Form K has no stamp. What follows?', '["K is not shown to be verified","K is definitely forged","Every form is unverified","K must be approved"]'::jsonb, 0, 'The rule supports only that verification is not established when the required stamp is absent Therefore, the correct option is "K is not shown to be verified." The other choices fail because the other choices assert fraud, universal failure, or approval without evidence.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('All verified forms carry a validation stamp. Form K has no stamp. What follows?')));
