INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 1, 'English', 'Which constitutional protection most directly limits a bill of attainder?', '["Government may not legislatively declare a person guilty and punish them","Every bill must concern a budget","Courts may never review statutes","A local ordinance becomes a treaty"]'::jsonb, 0, 'A bill of attainder is a legislative act that declares a person or group guilty and imposes punishment without a judicial trial Therefore, the correct option is "Government may not legislatively declare a person guilty and punish them." The other choices fail because the other choices describe unrelated legislative or international matters.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which constitutional protection most directly limits a bill of attainder?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 1, 'English', 'A public office denies a permit solely because an applicant criticized the mayor. Which principle is most implicated?', '["Freedom of expression and equal protection","The power to coin money","The rule on natural-born citizenship","The authority to audit accounts"]'::jsonb, 0, 'Punishing lawful criticism implicates expression and arbitrary unequal treatment Therefore, the correct option is "Freedom of expression and equal protection." The other choices fail because the other choices do not address retaliation for speech.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('A public office denies a permit solely because an applicant criticized the mayor. Which principle is most implicated?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 1, 'English', 'Which branch has the power to appropriate public funds?', '["Congress","The Supreme Court alone","A private bank","A barangay sports club"]'::jsonb, 0, 'Appropriation is a legislative function exercised by Congress through law Therefore, the correct option is "Congress." The other choices fail because the other choices do not enact the national budget.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which branch has the power to appropriate public funds?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 1, 'English', 'The constitutional requirement of just compensation applies when government:', '["Takes private property for public use","Publishes a weather bulletin","Conducts a public hearing","Counts election ballots"]'::jsonb, 0, 'Just compensation accompanies a public-use taking under eminent domain Therefore, the correct option is "Takes private property for public use." The other choices fail because the other choices do not involve taking private property.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('The constitutional requirement of just compensation applies when government:')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 1, 'English', 'Which statement best reflects freedom of religion?', '["The state may not establish a religion or prohibit its free exercise, subject to lawful limits","Only one religion may receive constitutional protection","Religious belief removes every criminal law","Public officials may deny service based on faith"]'::jsonb, 0, 'The Constitution protects free exercise and bars government establishment of religion Therefore, the correct option is "The state may not establish a religion or prohibit its free exercise, subject to lawful limits." The other choices fail because the other choices impose preference, immunity, or discrimination.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which statement best reflects freedom of religion?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 2, 'English', 'A public employee uses an official vehicle for a private vacation. Which RA 6713 norm is most directly violated?', '["Efficient, honest, and economical use of government resources","Natural-born citizenship","The right to suffrage","The rule on court jurisdiction"]'::jsonb, 0, 'RA 6713 requires government resources to be used efficiently, effectively, honestly, and economically for public purposes Therefore, the correct option is "Efficient, honest, and economical use of government resources." The other choices fail because the other choices concern unrelated constitutional subjects.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('A public employee uses an official vehicle for a private vacation. Which RA 6713 norm is most directly violated?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 2, 'English', 'Which conduct best demonstrates responsiveness to the public?', '["Explaining procedures clearly and attending to a transaction promptly","Sending an applicant from desk to desk without guidance","Using jargon to discourage questions","Ignoring a request until the deadline passes"]'::jsonb, 0, 'Responsiveness requires prompt, courteous, adequate service and understandable information Therefore, the correct option is "Explaining procedures clearly and attending to a transaction promptly." The other choices fail because the other choices create delay, confusion, or neglect.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which conduct best demonstrates responsiveness to the public?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 2, 'English', 'A public employee discovers a mistake in a submitted SALN. The ethical course is to:', '["Correct and resubmit it through the required review process","Hide the mistake until retirement","Delete the office copy","Ask a friend to sign a blank replacement"]'::jsonb, 0, 'Accurate disclosure and correction through the prescribed process protect the integrity of the SALN Therefore, the correct option is "Correct and resubmit it through the required review process." The other choices fail because the other choices conceal or falsify a public record.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('A public employee discovers a mistake in a submitted SALN. The ethical course is to:')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 4, 'English', 'Which waste-management choice follows the waste hierarchy most closely?', '["Prevent waste first, then reuse and recover materials before final disposal","Mix all waste and burn it in an open area","Dump reusable materials with residual waste","Send every item directly to a landfill"]'::jsonb, 0, 'Prevention, reuse, and recovery preserve resources before disposal is considered Therefore, the correct option is "Prevent waste first, then reuse and recover materials before final disposal." The other choices fail because the other choices increase waste and pollution.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which waste-management choice follows the waste hierarchy most closely?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 4, 'English', 'Mangroves help coastal communities mainly by:', '["Providing habitat and reducing wave and erosion impacts","Increasing plastic leakage","Removing all rainfall","Replacing every inland forest"]'::jsonb, 0, 'Mangroves provide habitat and can reduce coastal erosion and wave energy Therefore, the correct option is "Providing habitat and reducing wave and erosion impacts." The other choices fail because the other choices claim impossible or harmful effects.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Mangroves help coastal communities mainly by:')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 4, 'English', 'Which office practice reduces paper consumption without sacrificing records control?', '["Use an approved digital workflow with backups and retention rules","Delete files without authorization","Print every draft several times","Store sensitive records on an unprotected public drive"]'::jsonb, 0, 'A controlled digital workflow can reduce paper while preserving retention, access, and security Therefore, the correct option is "Use an approved digital workflow with backups and retention rules." The other choices fail because the other choices risk loss, waste, or unauthorized disclosure.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which office practice reduces paper consumption without sacrificing records control?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 5, 'English', 'The word ''meticulous'' most nearly means:', '["Very careful and exact","Carelessly improvised","Unable to notice detail","Unrelated to quality"]'::jsonb, 0, 'Meticulous describes work done with great care and attention to detail Therefore, the correct option is "Very careful and exact." The other choices fail because the other choices express carelessness or unrelated ideas.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('The word ''meticulous'' most nearly means:')));
