INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 7, 'English', 'Which sentence is grammatically correct?', '["Neither the memo nor the attachments are missing.","Neither the memo nor the attachments is missing.","Neither the memo nor the attachments be missing.","Neither memo nor attachments was missing are."]'::jsonb, 0, 'With neither-nor, the verb agrees with the nearer plural subject attachments, so are is correct Therefore, the correct option is "Neither the memo nor the attachments are missing.." The other choices fail because the other choices use incorrect agreement or sentence structure.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which sentence is grammatically correct?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 8, 'English', 'Which option correctly combines the ideas ''The file was old'' and ''It remained legible''?', '["Although the file was old, it remained legible.","The file was old it remained legible.","The file was old, it remained legible.","Although the file was old. It remained legible."]'::jsonb, 0, 'Although creates a dependent contrast clause joined to the independent clause Therefore, the correct option is "Although the file was old, it remained legible.." The other choices fail because the other choices are a run-on, comma splice, or fragment.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which option correctly combines the ideas ''The file was old'' and ''It remained legible''?')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 9, 'English', 'Which sentence best concludes a paragraph about secure password practices?', '["Strong password habits reduce avoidable account risks.","The office has a green door.","Some keyboards are wireless.","Yesterday had light traffic."]'::jsonb, 0, 'The first sentence returns to the paragraph topic and gives a concise closing idea Therefore, the correct option is "Strong password habits reduce avoidable account risks.." The other choices fail because the other choices introduce unrelated details.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Which sentence best concludes a paragraph about secure password practices?')));
