INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 15, 'English', 'Compute 7 multiplied by 8 minus 15.', '["41","31","56","71"]'::jsonb, 0, 'Multiply first: 7 times 8 is 56, then subtract 15 to get 41 Therefore, the correct option is "41." The other choices fail because the other choices omit or reverse the required operation.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Compute 7 multiplied by 8 minus 15.')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 16, 'English', 'Find the next term: 100, 90, 75, 55, __.', '["30","35","40","25"]'::jsonb, 0, 'The differences are minus 10, minus 15, minus 20, so subtract 25 from 55 to get 30 Therefore, the correct option is "30." The other choices fail because the other choices use the wrong next difference.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('Find the next term: 100, 90, 75, 55, __.')));
INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT 17, 'English', 'A printer produces 240 pages in 6 minutes. At the same rate, how many pages in 9 minutes?', '["360","300","400","420"]'::jsonb, 0, 'The rate is 240 divided by 6, or 40 pages per minute; 9 minutes gives 360 Therefore, the correct option is "360." The other choices fail because the other choices use an incorrect rate or duration.', 'active', 1, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('A printer produces 240 pages in 6 minutes. At the same rate, how many pages in 9 minutes?')));
